import Foundation
import GRDB
import Observation

/// Bundled MF Workouts data (read-only, generated by `scripts/catalog.ts`) merged with the owner's custom exercises.
@MainActor @Observable
final class ExerciseCatalog {
    private(set) var bundled: [Exercise]
    private let rankedBundled: [Exercise]
    private var byID: [ExerciseID: Exercise]
    private(set) var custom: [Exercise] = []
    /// Custom and bundled exercises in `Exercise.ranked` order, sorted once so lists only filter it.
    private(set) var all: [Exercise]
    /// Bumps whenever `all` changes, so views can key cached results on it.
    private(set) var revision = 0
    let equipment: [String: Equipment]
    let articles: [String: Article]

    init() {
        let decoded: [Exercise] = Self.load("exercises")
        let bundled = decoded.sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
        self.bundled = bundled
        rankedBundled = Exercise.ranked(nameSorted: bundled)
        all = rankedBundled
        byID = Dictionary(uniqueKeysWithValues: decoded.map { ($0.id, $0) })
        equipment = Dictionary(uniqueKeysWithValues: (Self.load("equipment") as [Equipment]).map { ($0.id, $0) })
        articles = Dictionary(uniqueKeysWithValues: (Self.load("articles") as [Article]).map { ($0.id, $0) })
    }

    private static func load<T: Decodable>(_ name: String) -> T {
        guard let url = Bundle.main.url(forResource: name, withExtension: "json") else {
            fatalError("Missing \(name).json. Regenerate it with `bun app-ios/scripts/catalog.ts`.")
        }
        do {
            return try JSONDecoder().decode(T.self, from: Data(contentsOf: url))
        } catch {
            fatalError("\(name).json does not match its Swift type: \(error)")
        }
    }

    /// Markdown with "Setting up", "Exercise technique", and "Description" sections. The first call maps the bundled
    /// pack, so call it off main or from an action, never from `body`.
    func instructions(for exercise: Exercise) -> String? {
        exercise.hasInstructions ? MarkdownPack.bundled.instructions(exercise.id) : nil
    }

    @ObservationIgnored private var customObservation: AnyDatabaseCancellable?

    /// Keeps the custom exercises current with the store.
    func observeCustom(in store: LocalStore) {
        customObservation = ValueObservation.trackingConstantRegion { try CustomExercise.all.fetch($0).map(\.exercise) }
            .removeDuplicates()
            .start(
                in: store.database.pool,
                scheduling: .immediate,
                onError: { LocalStore.log.error("Custom exercise observation failed: \(String(describing: $0))") },
                onChange: { [weak self] in self?.setCustom($0) }
            )
    }

    func setCustom(_ exercises: [Exercise]) {
        guard exercises != custom else { return }
        for old in custom { byID[old.id] = nil }
        custom = exercises
        for exercise in exercises { byID[exercise.id] = exercise }
        all = Exercise.mergeRanked(Exercise.ranked(exercises), rankedBundled)
        revision += 1
    }

    func exercise(_ id: ExerciseID) -> Exercise? { byID[id] }

    /// Name for display even when an ID no longer resolves, so history never shows a blank row.
    func name(_ id: ExerciseID) -> String { byID[id]?.name ?? "Unknown exercise" }
}

/// The order every exercise list shows: search boost first, then name.
extension Exercise {
    static func ranksBefore(_ a: Exercise, _ b: Exercise) -> Bool {
        a.searchBoost != b.searchBoost
            ? a.searchBoost > b.searchBoost
            : a.name.localizedCaseInsensitiveCompare(b.name) == .orderedAscending
    }

    static func ranked(_ exercises: [Exercise]) -> [Exercise] {
        exercises.sorted(by: ranksBefore)
    }

    /// `ranked` for exercises already sorted by name, without comparing names again.
    static func ranked(nameSorted exercises: [Exercise]) -> [Exercise] {
        Dictionary(grouping: exercises, by: \.searchBoost).sorted { $0.key > $1.key }.flatMap(\.value)
    }

    /// Merges two lists that are each in `ranked` order.
    static func mergeRanked(_ a: [Exercise], _ b: [Exercise]) -> [Exercise] {
        var merged: [Exercise] = []
        merged.reserveCapacity(a.count + b.count)
        var i = a.startIndex, j = b.startIndex
        while i < a.endIndex, j < b.endIndex {
            if ranksBefore(b[j], a[i]) {
                merged.append(b[j])
                j += 1
            } else {
                merged.append(a[i])
                i += 1
            }
        }
        return merged + a[i...] + b[j...]
    }
}
